// Parameterized screenshot driver: node screenshot.mjs <url> <outPath> [waitMs] [width] [height] [fullPage]
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';

const [url, outPath, waitMs = '4000', width = '1280', height = '900', fullPage = ''] = process.argv.slice(2);
if (!url || !outPath) {
  console.error('usage: node screenshot.mjs <url> <outPath> [waitMs] [width] [height] [fullPage]');
  process.exit(2);
}

const browser = await chromium.launch();
try {
  const ctx = await browser.newContext({
    ignoreHTTPSErrors: true,
    viewport: { width: Number(width), height: Number(height) },
    deviceScaleFactor: 1,
  });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  page.on('requestfailed', (r) => errors.push(`requestfailed: ${r.url().slice(0, 120)} ${r.failure()?.errorText}`));
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 45000 });
  await page.waitForTimeout(Number(waitMs));
  await page.screenshot({ path: outPath, fullPage: fullPage === 'full' });
  console.log(`saved ${outPath}`);
  if (errors.length) console.log('notes:\n' + errors.slice(0, 8).join('\n'));
} finally {
  await browser.close();
}

